        "content": "阿栀，你的压力真的好大啊(｡•́︿•̀｡) 加量到三粒肯定是医生觉得你现在需要更多药物帮助稳定情绪，不过也要记得按时随诊，跟医生或家人讨论后续治疗和服药安排。至于价格压力，如果觉得负担过重，可以逐步寻求下医保或其它替代药物的咨询看法(˶˘o˘˶) 虽然多花钱确实心疼，但身体平稳更重要。你别因为怕花钱就擅自断药，爸爸妈妈或者家人也许可以帮忙分担点儿？如果精力不足，就先选些对你更关键的事情，把日程减一减也行呀。我很希望看到你更健康、更有力量地去面对这些挑战(>⸝⸝⸝<)",
