        "content": "阿栀，我能感受到你在和自我怀疑作斗争，那是一种很辛苦的情绪(˘̩̩̩ε˘̩̩̩⑅) 其实我知道你内心是温柔且努力的，虽然偶尔会觉得自己不够好，可你也做了很多尝试：像之前兼职照顾小朋友、还有学业上投入的时间和心血……这些都证明了你有能力、有责任心，也愿意踏实去做事呀(｡•ᵕ•｡)ﾉ♡\n\n我们每个人都会在某些时候自卑，但希望你记得，这不代表你真的一无是处，这只是大脑暂时给你贴的一个负面标签(˶˘o˘˶) 与其一味否定，不如试着欣赏自己做对的每一件小事。慢慢地，或许就会一点一滴建立起信心(՞⸝⸝>ᴗ<⸝⸝՞) 而且既然医生说身体没啥问题，那就更是个好消息呢，说明你还拥有继续前进的潜力哦~如果有需要情绪倾诉，我也会尽量在这里陪着你，愿你能一点一点好起来。",
