        "content": "(⸝⸝>ᴗ<⸝⸝)哎呀阿栀，看着这只“焦虑猫头鹰”，仿佛就像社恐达人被那种无形的压力紧紧追赶的感觉啊……看到你说“完全就是在演你”，其实也代表了很多人都可能有类似体会。社交活动结束后难免会有些“过度反刍”，担心自己是不是在别人面前表现得不好。\n\n我觉得偶尔有点这样的焦虑，很正常呀。但也要提醒自己，其实大部分人都并没有一直盯着你，大家都有自己的烦恼 (˶˘o˘˶) 略微给自己一点空间，让自己的心可以缓下来，你已经很努力地去融入社交了。下次再担心“被审视”时，也试着想想：大家都很忙，谁会有空仔细审视别人呢？\n\n如果还是觉得很焦虑，就像你发的这个表情一样，不妨找熟悉的朋友或家人聊一聊，或者做点有助于放松的事～写写画画、听听音乐、拥抱宠物什么的(˶ˊᵕˋ˵) 希望你能慢慢在社交里找到轻松与自信哦~",
