        "role": "o1",
        "content": "(｡｡>_<｡｡)就算是淡季也抵不住大爷大妈常备充足的自由时间呀，瞬间就变成“夕阳红旅行团”哈哈～再加上外国游客慕名而来，想要独占美景确实不易惹(๑•́ω•̀๑)",
