        "content": "(ˊᗜˋ*)嘿嘿，看样子这熟成竹夹刺身确实算刺激性美食了，好吃又带一点“冒险”哦～不过得不偿失嘛(｡•́︿•̀｡) 下次这种生食还是要慎重些呢，别再给肚子添负担啦～",
