        "role": "o1",
        "content": "(ᐡ ̥_ ̫ _ ̥ᐡ)鲷鱼确实常被说是生食界的“安全牌”呢，不仅口感鲜甜也不太让人闹肚子～看来已经找到适合你的日料宝藏啦(｡>∀<｡)下次可以放心点个鲷鱼刺身啦～",
